mapper.select:
select employee_id, scenario, status, action_id, task_id, version
from sys_hr_renewal_guard
where employee_id = #{employeeId}
  and scenario = #{scenario}
for update

mapper.update:
update sys_hr_renewal_guard
set status = 'ACTIVE',
    task_id = #{taskId},
    version = version + 1,
    update_time = sysdate()
where employee_id = #{employeeId}
  and scenario = #{scenario}
  and status = 'RESERVED'
  and action_id = #{actionId}
  and task_id is null
  and version = #{expectedVersion}

update sys_hr_renewal_guard
set action_id = #{newActionId},
    task_id = #{newTaskId},
    version = version + 1,
    update_time = sysdate()
where employee_id = #{employeeId}
  and scenario = #{scenario}
  and status = 'ACTIVE'
  and action_id = #{expectedActionId}
  and task_id = #{expectedTaskId}

update sys_hr_renewal_guard
set status = 'IDLE',
    action_id = null,
    task_id = null,
    version = version + 1,
    update_time = sysdate()
where employee_id = #{employeeId}
  and scenario = #{scenario}
  and status = 'ACTIVE'
  and action_id = #{actionId}
  and task_id = #{taskId}

update sys_hr_renewal_guard
set status = 'IDLE',
    action_id = null,
    task_id = null,
    version = version + 1,
    update_time = sysdate()
where employee_id = #{employeeId}
  and scenario = #{scenario}
  and status = 'RESERVED'
  and action_id = #{actionId}
  and task_id is null
  and version = #{expectedVersion}

update sys_hr_renewal_guard
set status = 'IDLE',
    action_id = null,
    task_id = null,
    version = version + 1,
    update_time = sysdate()
where employee_id = #{employeeId}
  and scenario = #{scenario}
  and status = 'ACTIVE'
  and task_id = #{taskId}
